ue="{{ $account['code'] }}">{{ $account['code'] }} — {{ $account['name'] }}</option>@endif @endforeach</select></label><label id="ewt-link-field">Existing posted journal (optional)<select name="linked_source"><option value="">Tag only — no journal</option>@foreach($summary['journals'] as $journal)<option value="{{ $journal->source_key }}">{{ $journal->number }} — {{ $journal->transaction_date }}</option>@endforeach</select></label><label id="ewt-penalty-field" hidden>Penalty expense account<select name="penalty_account"><option value="7290">7290 — Penalties &amp; Surcharges</option>@foreach($summary['accounts'] as $account) @if($account['type'] === 'Expense' && $account['code'] !== '7290')<option value="{{ $account['code'] }}">{{ $account['code'] }} — {{ $account['name'] }}</option>@endif @endforeach</select></label></div><div id="ewt-preview" hidden aria-live="polite"></div><p id="ewt-payment-error" role="alert"></p><footer><button type="button" class="button secondary compact" data-ewt-close>Cancel</button><button type="submit" class="button secondary compact" id="ewt-review">Preview payment</button><button type="button" class="button primary compact" id="ewt-confirm" hidden>Confirm payment record</button></footer></form></dialog>
